export function useROICanvas() {
  const ref = useRef(null);
  const roiRef = useRef(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');

    const W = canvas.clientWidth || 590;
    const H = canvas.clientHeight || 280;

    canvas.width = W;
    canvas.height = H;

    let roi = {
      x: W * 0.28,
      y: H * 0.18,
      w: W * 0.44,
      h: H * 0.64,
    };

    // Make the current ROI available outside this effect
    roiRef.current = roi;

    let dragging = null;
    const HANDLE_R = 7;

    const handles = () => [
      { id: 'tl', x: roi.x, y: roi.y },
      { id: 'tr', x: roi.x + roi.w, y: roi.y },
      { id: 'bl', x: roi.x, y: roi.y + roi.h },
      { id: 'br', x: roi.x + roi.w, y: roi.y + roi.h },
    ];

    function draw() {
      ctx.fillStyle = '#1A2B3C';
      ctx.fillRect(0, 0, W, H);

      ctx.strokeStyle = 'rgba(255,255,255,0.06)';
      ctx.lineWidth = 1;

      for (let x = 0; x < W; x += 24) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, H);
        ctx.stroke();
      }

      for (let y = 0; y < H; y += 24) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(W, y);
        ctx.stroke();
      }

      // Dark overlay outside ROI
      ctx.fillStyle = 'rgba(0,0,0,0.42)';
      ctx.fillRect(0, 0, W, roi.y);
      ctx.fillRect(0, roi.y, roi.x, roi.h);
      ctx.fillRect(
        roi.x + roi.w,
        roi.y,
        W - roi.x - roi.w,
        roi.h
      );
      ctx.fillRect(
        0,
        roi.y + roi.h,
        W,
        H - roi.y - roi.h
      );

      // ROI border
      ctx.strokeStyle = '#E8741A';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(roi.x, roi.y, roi.w, roi.h);

      // ROI label
      ctx.fillStyle = 'rgba(232,116,26,0.85)';
      ctx.fillRect(roi.x, roi.y - 18, 72, 18);

      ctx.fillStyle = '#fff';
      ctx.font = '9px DM Mono, monospace';
      ctx.fillText('ROI ACTIVE', roi.x + 6, roi.y - 6);

      // Corner handles
      handles().forEach((h) => {
        ctx.beginPath();
        ctx.arc(h.x, h.y, HANDLE_R, 0, Math.PI * 2);
        ctx.fillStyle = '#E8741A';
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      });
    }

    const getHandle = (mx, my) =>
      handles().find(
        (h) =>
          Math.hypot(h.x - mx, h.y - my) <
          HANDLE_R + 4
      );

    const pos = (e) => {
      const r = canvas.getBoundingClientRect();
      const t = e.touches ? e.touches[0] : e;

      return {
        x: t.clientX - r.left,
        y: t.clientY - r.top,
      };
    };

    const onDown = (e) => {
      const { x, y } = pos(e);
      const h = getHandle(x, y);

      if (h) {
        dragging = h.id;
      }
    };

    const onMove = (e) => {
      const { x, y } = pos(e);

      if (!dragging) {
        canvas.style.cursor = getHandle(x, y)
          ? 'pointer'
          : 'crosshair';

        return;
      }

      const min = 40;

      if (dragging === 'tl') {
        const nx = Math.min(
          x,
          roi.x + roi.w - min
        );

        const ny = Math.min(
          y,
          roi.y + roi.h - min
        );

        roi.w += roi.x - nx;
        roi.h += roi.y - ny;

        roi.x = nx;
        roi.y = ny;

      } else if (dragging === 'tr') {
        roi.w = Math.max(
          min,
          x - roi.x
        );

        const ny = Math.min(
          y,
          roi.y + roi.h - min
        );

        roi.h += roi.y - ny;
        roi.y = ny;

      } else if (dragging === 'bl') {
        const nx = Math.min(
          x,
          roi.x + roi.w - min
        );

        roi.w += roi.x - nx;
        roi.x = nx;

        roi.h = Math.max(
          min,
          y - roi.y
        );

      } else if (dragging === 'br') {
        roi.w = Math.max(
          min,
          x - roi.x
        );

        roi.h = Math.max(
          min,
          y - roi.y
        );
      }

      // Update the accessible ROI
      roiRef.current = { ...roi };

      draw();
    };

    const onUp = () => {
      dragging = null;
    };

    canvas.addEventListener('mousedown', onDown);
    canvas.addEventListener('mousemove', onMove);
    canvas.addEventListener('mouseup', onUp);
    canvas.addEventListener('mouseleave', onUp);

    draw();

    return () => {
      canvas.removeEventListener('mousedown', onDown);
      canvas.removeEventListener('mousemove', onMove);
      canvas.removeEventListener('mouseup', onUp);
      canvas.removeEventListener('mouseleave', onUp);
    };
  }, []);

  // Return both canvas and ROI information
  return {
    canvasRef: ref,
    getROI: () => roiRef.current,
  };
}
